// Star animated visuals engine — renders each [data-anim] from window.STAR_ANIMS and loops it like a GIF.
// Plays only while on screen (IntersectionObserver), restarts when a hidden tab becomes visible,
// and shows the finished frame for visitors who prefer reduced motion.
(function(){
  var DATA = window.STAR_ANIMS || {};
  var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function h(tag, cls, txt){ var e=document.createElement(tag); if(cls) e.className=cls; if(txt!=null) e.textContent=txt; return e; }
  function build(node){
    var cfg = DATA[node.getAttribute('data-anim')]; if(!cfg) return null;
    node.innerHTML=''; node.classList.add('anim');
    node.setAttribute('role','img'); node.setAttribute('aria-label', cfg.alt || cfg.title);
    var head=h('div','a-head'); var d=h('span','a-dots'); d.innerHTML='<i></i><i></i><i></i>'; head.appendChild(d);
    head.appendChild(h('span','a-title',cfg.title));
    var live=h('span','a-live'); live.appendChild(h('i')); live.appendChild(document.createTextNode(cfg.tag||'Live')); head.appendChild(live);
    node.appendChild(head);
    var body=h('div','a-body'); node.appendChild(body);
    var p={lines:[],bars:[],steps:[],scan:null};
    if(cfg.doc){
      var doc=h('div','a-doc'); doc.appendChild(h('div','a-doc-name',cfg.doc.name));
      cfg.doc.lines.forEach(function(l){ var r=h('div','a-line'); r.appendChild(h('span','k',l[0])); r.appendChild(h('span','v',l[1])); doc.appendChild(r); p.lines.push(r); });
      p.scan=h('div','a-scan'); doc.appendChild(p.scan); body.appendChild(doc);
    }
    if(cfg.bars){
      var cmp=h('div','a-cmp'); if(cfg.barsTitle) cmp.appendChild(h('div','a-cmp-t',cfg.barsTitle));
      cfg.bars.forEach(function(b){ var r=h('div','a-bar'); r.appendChild(h('span','k',b[0])); var tr=h('span','tr'); var f=h('i',b[3]||''); f.setAttribute('data-w',b[1]); tr.appendChild(f); r.appendChild(tr); r.appendChild(h('span','v',b[2])); cmp.appendChild(r); p.bars.push(f); });
      body.appendChild(cmp);
    }
    var st=h('div','a-steps');
    cfg.steps.forEach(function(s){
      var r=h('div','a-step'); r.appendChild(h('time',null,s[0]));
      var m=h('div'); m.appendChild(h('b',null,s[1])); if(s[2]) m.appendChild(h('small',null,s[2])); r.appendChild(m);
      var c=h('span','chip work','Working'); c.setAttribute('data-k',s[3]||'ok'); c.setAttribute('data-l',s[4]||'Done'); r.appendChild(c);
      st.appendChild(r); p.steps.push({row:r,chip:c});
    });
    body.appendChild(st);
    var ft=h('div','a-foot'); var f=cfg.foot||['','']; ft.appendChild(h('span',null,f[0])); ft.appendChild(h('span',null,f[1])); node.appendChild(ft); p.foot=ft;
    var pg=h('div','a-prog'); p.prog=h('i'); pg.appendChild(p.prog); node.appendChild(pg);
    return p;
  }
  function reset(p){
    p.lines.forEach(function(l){ l.classList.remove('hit'); });
    p.bars.forEach(function(b){ b.style.width='0'; });
    p.steps.forEach(function(s){ s.row.classList.remove('in'); s.chip.className='chip work'; s.chip.textContent='Working'; });
    p.foot.classList.remove('in');
    p.prog.style.transition='none'; p.prog.style.width='0';
    if(p.scan) p.scan.classList.remove('go');
  }
  function finalFrame(p){
    p.lines.forEach(function(l){ l.classList.add('hit'); });
    p.bars.forEach(function(b){ b.style.width=b.getAttribute('data-w'); });
    p.steps.forEach(function(s){ s.row.classList.add('in'); s.chip.className='chip '+s.chip.getAttribute('data-k'); s.chip.textContent=s.chip.getAttribute('data-l'); });
    p.foot.classList.add('in'); p.prog.style.width='100%';
  }
  function run(node){
    var p=node._p, tok=++node._tok, t=0, q=[];
    reset(p); node.classList.remove('fade'); void node.offsetWidth;
    function at(ms,fn){ q.push([ms,fn]); }
    if(p.scan) at(60,function(){ p.scan.classList.add('go'); });
    p.lines.forEach(function(l){ t+=320; at(t,function(){ l.classList.add('hit'); }); });
    p.bars.forEach(function(b){ t+=500; at(t,function(){ b.style.width=b.getAttribute('data-w'); }); });
    p.steps.forEach(function(s){
      t+=420; at(t,function(){ s.row.classList.add('in'); });
      t+=760; at(t,function(){ s.chip.className='chip '+s.chip.getAttribute('data-k'); s.chip.textContent=s.chip.getAttribute('data-l'); });
    });
    t+=400; at(t,function(){ p.foot.classList.add('in'); });
    var total=t;
    at(40,function(){ p.prog.style.transition='width '+total+'ms linear'; p.prog.style.width='100%'; });
    at(total+2800,function(){ node.classList.add('fade'); });
    at(total+3300,function(){ if(node._vis){ run(node); } else { node._running=false; } });
    q.forEach(function(x){ setTimeout(function(){ if(node._tok===tok) x[1](); }, x[0]); });
  }
  var io = ('IntersectionObserver' in window) ? new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      var n=e.target; n._vis=e.isIntersecting;
      if(e.isIntersecting && !n._running){ n._running=true; run(n); }
      else if(!e.isIntersecting){ n._tok++; n._running=false; }
    });
  },{threshold:0.2}) : null;
  document.querySelectorAll('[data-anim]').forEach(function(n){
    var p=build(n); if(!p) return; n._p=p; n._tok=0;
    if(reduce || !io){ finalFrame(p); return; }
    reset(p); io.observe(n);
  });
})();
